# Completa la línea marcada y compruébala con py check.
def mas_votada(muestras):
    conteo = {}
    for m in muestras:
        conteo[m] = conteo.get(m, 0) + 1
    return muestras[0]   # cambia: devuelve la respuesta con el conteo mas alto

print(mas_votada(["a", "b", "b", "c", "b"]))   # b
